INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die doppelte Buchführung nur für große Unternehmen gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMUs nutzen sie"}, {"text": "Ja", "correct": false, "because": "Größe egal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip liegt der doppelten Buchführung zugrunde?', 3, '[{"text": "Jede Transaktion wird doppelt erfasst", "correct": true, "because": "Soll und Haben"}, {"text": "Einmalige Erfassung", "correct": false, "because": "Einfache Buchführung"}, {"text": "Zufällige Zuordnung", "correct": false, "because": "Nicht systematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konten werden in der doppelten Buchführung genutzt?', 5, '[{"text": "Aktiva", "correct": true, "because": "Vermögenswerte"}, {"text": "Passiva", "correct": true, "because": "Schulden und Eigenkapital"}, {"text": "Farbcodes", "correct": false, "because": "Kein Buchhaltungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Doppelte Buchführung nutzt Soll und Haben. b) Sie erfasst nur Einnahmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Ausgaben"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der doppelten Buchführung?', 4, '[{"text": "Bilanzgleichheit", "correct": false, "because": "Aktiva = Passiva"}, {"text": "Transaktionszuordnung", "correct": false, "because": "Soll und Haben"}, {"text": "Papierdesign", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die doppelte Buchführung nur manuell ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch softwaregestützt"}, {"text": "Ja", "correct": false, "because": "ERP-Systeme nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Konto wird im Soll gebucht, wenn ich Ware kaufe?', 3, '[{"text": "Aufwandskonto", "correct": true, "because": "Kosten entstehen"}, {"text": "Einnahmekonto", "correct": false, "because": "Kein Gewinn"}, {"text": "Eigenkapital", "correct": false, "because": "Nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien gelten für die doppelte Buchführung?', 5, '[{"text": "Jede Buchung hat Gegenbuchung", "correct": true, "because": "Soll = Haben"}, {"text": "Bilanzgleichung", "correct": true, "because": "Aktiva = Passiva"}, {"text": "Einmalige Erfassung", "correct": false, "because": "Doppelte Erfassung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Doppelte Buchführung zeigt Vermögen. b) Sie ist optional für Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pflicht für viele"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die doppelte Buchführung?', 4, '[{"text": "Kontenplan", "correct": false, "because": "Grundlage"}, {"text": "Bilanz", "correct": false, "because": "Ergebnis"}, {"text": "Künstlerische Gestaltung", "correct": true, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die doppelte Buchführung gesetzlich vorgeschrieben?', 2, '[{"text": "Ja", "correct": true, "because": "Für Kapitalgesellschaften"}, {"text": "Nein", "correct": false, "because": "Pflicht für viele"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kontenarten gibt es in der doppelten Buchführung?', 4, '[{"text": "Erfolgskonten", "correct": true, "because": "Aufwand und Ertrag"}, {"text": "Bestandskonten", "correct": true, "because": "Aktiva und Passiva"}, {"text": "Farbenkonten", "correct": false, "because": "Kein Begriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die doppelte Buchführung nur für Steuerzwecke ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Unternehmensführung"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der doppelten Buchführung?', 3, '[{"text": "Genauigkeit", "correct": true, "because": "Fehler vermeiden"}, {"text": "Schnelligkeit", "correct": false, "because": "Präzision zählt"}, {"text": "Optisches Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Doppelte Buchführung erfasst Vermögen. b) Sie nutzt nur ein Konto.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mindestens zwei Konten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die doppelte Buchführung?', 5, '[{"text": "Transparenz", "correct": true, "because": "Klare Übersicht"}, {"text": "Fehlererkennung", "correct": true, "because": "Soll = Haben"}, {"text": "Schnelle Bearbeitung", "correct": false, "because": "Genauigkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der doppelten Buchführung unwichtig?', 3, '[{"text": "Kontenrahmen", "correct": false, "because": "Struktur nötig"}, {"text": "Bilanzgleichung", "correct": false, "because": "Kernprinzip"}, {"text": "Papiergröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die doppelte Buchführung digital erfolgen?', 3, '[{"text": "Ja", "correct": true, "because": "Software wie ERP"}, {"text": "Nein", "correct": false, "because": "Digital möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die doppelte Buchführung Gewinn zeigt?', 2, '[{"text": "Ja", "correct": true, "because": "Über Erfolgskonten"}, {"text": "Nein", "correct": false, "because": "Gewinn ermittelbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für die doppelte Buchführung zentral?', 4, '[{"text": "Soll und Haben", "correct": true, "because": "Doppelte Erfassung"}, {"text": "Einzelbuchung", "correct": false, "because": "Einfache Methode"}, {"text": "Manuelle Notizen", "correct": false, "because": "Systematisch"}]');
